import numpy as np,pandas as pd,zipfile
from pathlib import Path
P=Path(__file__).parent; ROOT=Path(__import__('os').environ.get('LSC_DATA_DIR',str(P))); L=['EDM','ATH','BONPCP','LYD','MAC','MED','WAB-PCP','PRV-PCP']; start=pd.Timestamp('2021-01-01'); dates=pd.date_range(start,'2026-08-31'); T=len(dates); ix=lambda s:(pd.to_datetime(s,format='mixed')-start).dt.days
z=zipfile.ZipFile(ROOT/'datasets.zip'); s=pd.concat([pd.read_csv(z.open(n),encoding='utf-8-sig',low_memory=False) for n in z.namelist() if n.startswith('datasets/') and 'PCP' in n and n.endswith('.csv')],ignore_index=True);s['t']=ix(s['Posting Date']);s=s.drop_duplicates(['Company','Document No','Order No','No','Location Code','Quantity','t','UWI','Sales Expected']);s=s[(s.Company=='LSI')&s['Location Code'].isin(L)&s.t.between(0,T-1)]
