j24=(pd.Timestamp('2024-01-01')-start).days;j25=(pd.Timestamp('2025-01-01')-start).days;jt=(pd.Timestamp('2026-01-01')-start).days;jm=(pd.Timestamp('2026-05-01')-start).days;jtest=(pd.Timestamp('2026-06-01')-start).days
