tr=d[d['Entry Type Description'].eq('Transfer') & d['Location Code'].isin(L)&d['Item No.'].isin(code)&d['Serial No.'].notna()&d['Order No.'].notna()]; neg=tr[tr.Quantity<0][['Order No.','Serial No.','Item No.','Location Code','t']].drop_duplicates();pos=tr[tr.Quantity>0][['Order No.','Serial No.','Item No.','Location Code','t']].drop_duplicates(); m=neg.merge(pos,on=['Order No.','Serial No.','Item No.'],suffixes=('_o','_d'));m=m[(m['Location Code_o']!=m['Location Code_d'])&((m.t_d-m.t_o).abs()<=45)].copy();m['reverse']=m.t_d<m.t_o;m['distance']=(m.t_d-m.t_o).abs();m=m.sort_values(['reverse','distance','t_d']).drop_duplicates(['Order No.','Serial No.','Item No.','Location Code_o','t_o']).drop_duplicates(['Order No.','Serial No.','Item No.','Location Code_d','t_d']);print('reverse matched transfers',m.reverse.sum(),'test source reverse',m.loc[m.t_o>=jtest,'reverse'].sum(),flush=True);m=m.drop(columns=['reverse','distance']); moves=np.zeros((T,K,8,8),np.int16); arrivals=np.zeros_like(ledger); departures=np.zeros_like(ledger)
