price=s[s.Quantity>0].copy();price['p']=price['Sales Expected']/price.Quantity;price=price[price.p>0]; pp=price[price.t<jt].groupby('No').p.median().reindex(codes); fallback=np.where(pd.Series(codes).str.contains('^R|^CDR|^PVR'),1400,2400); val=pp.fillna(pd.Series(fallback,index=codes)).to_numpy(); print('moves',moves.sum(),'residual test +/-',np.maximum(resid[jtest:],0).sum(),np.maximum(-resid[jtest:],0).sum(), 'opening $', (pre[jtest]*val[:,None]).sum(), 'imputed price',pp.isna().sum(),flush=True)
